const originalFilterbar=filterbar;filterbar=function(extra=false){return originalFilterbar(extra&&state.report!=='profit'&&state.report!=='quality')};
function registerTools(){let context=document.modelContext;if(!context?.registerTool)return;let lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const list=[{name:'read_order_hub_demo_summary',title:'อ่านสรุป Order Hub สาธิต',description:'Read the current demo report filters and computed summary; no live platform access.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('Unexpected input');return {demo:true,view:state.view,filters:{from:state.from,to:state.to,channel:state.channel},summary:stats(filtered()),received:sum(filteredPayouts(),p=>p.net)}}},{name:'set_order_hub_demo_filters',title:'เลือกตัวกรองรายงานสาธิต',description:'Set visible channel and date filters for demo reports. No order mutation or real API calls.',inputSchema:{type:'object',properties:{channel:{type:'string',enum:['',...CHANNELS.map(c=>c.name)]},from:{type:'string'},to:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Object required');for(let [k,v] of Object.entries(input)){if(!['channel','from','to'].includes(k)||typeof v!=='string')throw Error('Invalid filter');if(k==='channel'&&!['',...CHANNELS.map(c=>c.name)].includes(v))throw Error('Unknown channel');if(k!=='channel'&&v!==''&&(!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(Date.parse(v))||new Date(v).toISOString().slice(0,10)!==v))throw Error('Invalid date')}let next={...state,...input};if(next.from&&next.to&&next.from>next.to)throw Error('Invalid date range');Object.assign(state,input);state.selected.clear();state.page=1;shell();return {demo:true,summary:stats(filtered())}}}];for(let t of list)try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}

